import { shopZone, zoneGroupKey } from './shopAreas';
import { nearbyShops, sameShopPosition } from './shopLocation';

export function shopMapContext(target, catalog, zones) {
  const selected = catalog.find(s => sameShopPosition(s, target)) || target;
  const anchor = shopZone(selected, zones);
  if (!anchor) return { anchor: null, ownerType: null, ownerId: null, center: target, shops: nearbyShops(catalog, target), arrivals: [] };
  const group = zoneGroupKey(anchor);
  const shops = catalog.filter(row => {
    const match = shopZone(row, zones);
    return match && zoneGroupKey(match) === group;
  });
  const arrivals = zones.filter(z => z.serverKey === anchor.serverKey && z.dimensionKey === anchor.dimensionKey && zoneGroupKey(z) === group);
  return { anchor, ownerType: anchor.shopAreaId ? 'area' : 'warp', ownerId: anchor.shopAreaId || anchor.id,
    center: { x: anchor.centerX, z: anchor.centerZ }, shops, arrivals };
}

export function fittedMapRadius(center, shops, arrivals = []) {
  let furthest = 0;
  for (const row of shops) furthest = Math.max(furthest, Math.hypot(row.x - center.x, row.z - center.z));
  for (const zone of arrivals) furthest = Math.max(furthest, Math.hypot(zone.centerX - center.x, zone.centerZ - center.z));
  return Math.max(12, Math.ceil(furthest * 1.12 + 3));
}
