import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { MapPin, Minus, Plus, Maximize2, Navigation } from 'lucide-react';
import { shopMapContext, fittedMapRadius } from '@/lib/shopMap';
import { exactCoins, shopLocationKey, sameShopPosition } from '@/lib/shopLocation';
import { stockLabel } from '@/lib/shopStock';
import { fetchShopMap } from '@/lib/castiaClient';

const control = 'inline-flex items-center justify-center gap-1.5 rounded-sm border border-white/10 bg-white/[0.04] px-3 py-2 text-xs text-zinc-300 hover:bg-indigo-500/15 hover:text-white disabled:opacity-30';

export default function ShopContextMap({target, catalog, zones, onSelect}) {
  const viewportId = useId().replaceAll(':', '');
  const context = useMemo(() => shopMapContext(target, catalog, zones), [target, catalog, zones]);
  const [layer, setLayer] = useState(`cave:${Math.floor(target.y/16)}`);
  const [terrain, setTerrain] = useState(null);
  const [terrainLoading, setTerrainLoading] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [focused, setFocused] = useState(null);
  const [seller, setSeller] = useState('');
  const [center, setCenter] = useState(context.center);
  const [dragging, setDragging] = useState(false);
  const gesture = useRef(null);
  const suppressClick = useRef(false);
  const caveLayers = useMemo(() => [...new Set(context.shops.map(s => Math.floor(s.y/16)))].sort((a,b) => a-b), [context.shops]);
  const sellers = [...new Set(context.shops.map(s => s.seller))].sort();
  const selectedCaveLayer = layer.startsWith('cave:') ? Number(layer.slice(5)) : null;
  const band = context.shops.filter(s => (layer === 'surface' || Math.floor(s.y/16) === selectedCaveLayer) && (!seller || s.seller === seller));
  const [fit, setFit] = useState(() => fittedMapRadius(context.center, context.shops, context.arrivals));
  const radius = fit / zoom;
  const scale = 200 / radius;
  const projectX = x => 240 + (x-center.x)*scale;
  const projectZ = z => 240 + (z-center.z)*scale;
  const visible = band.filter(s => Math.abs(s.x-center.x) <= radius && Math.abs(s.z-center.z) <= radius);
  const selectMarker = rows => {
    setFocused(rows);
    onSelect(rows[0]);
  };
  const startDrag = event => {
    if (!event.isPrimary || event.button !== 0) return;
    const svg = event.currentTarget;
    const rect = svg.getBoundingClientRect();
    suppressClick.current = false;
    gesture.current = { id: event.pointerId, x: event.clientX, y: event.clientY, center, units: 480 / rect.width / scale, moved: false };
  };
  const moveDrag = event => {
    const g = gesture.current;
    if (!g || g.id !== event.pointerId) return;
    const dx = event.clientX-g.x, dy = event.clientY-g.y;
    if (!g.moved && Math.hypot(dx,dy) < 5) return;
    g.moved = true;
    suppressClick.current = true;
    event.currentTarget.setPointerCapture(event.pointerId);
    setDragging(true);
    setCenter({x:g.center.x-dx*g.units,z:g.center.z-dy*g.units});
  };
  const endDrag = event => {
    if (gesture.current?.id !== event.pointerId) return;
    gesture.current = null;
    setDragging(false);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
  };
  // Several signs can share an X/Z position or lie within a few pixels. Give
  // them one selectable marker and expose every offer in the list below.
  const markerGroups = new Map();
  for (const row of visible) {
    const key = `${Math.round(projectX(row.x)/10)},${Math.round(projectZ(row.z)/10)}`;
    if (!markerGroups.has(key)) markerGroups.set(key, []);
    markerGroups.get(key).push(row);
  }
  const focusedRows = focused?.filter(s => visible.includes(s)) || [];
  const list = focusedRows.length ? focusedRows : visible;
  const step = radius > 128 ? 64 : radius > 64 ? 32 : radius > 24 ? 16 : 8;
  const ticks = coordinate => Array.from({length: Math.ceil(radius*2/step)+1}, (_,i) => Math.ceil((coordinate-radius)/step)*step+i*step).filter(n=>n<=coordinate+radius);
  const centerLabel = context.anchor ? `/pw ${context.anchor.warpName}` : 'Selected sign';
  const terrainTiles = terrain?.tiles?.filter(tile => layer === 'surface'
    ? tile.layerKind === 'surface'
    : tile.layerKind === 'cave' && tile.caveLayer === selectedCaveLayer) || [];

  useEffect(() => {
    setCenter(context.center);
    setFit(fittedMapRadius(context.center, context.shops, context.arrivals));
    setZoom(1); setFocused(null);
  }, [context.ownerType, context.ownerId]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (!context.ownerType || !context.ownerId) { setTerrain(null); return undefined; }
    const controller = new AbortController();
    setTerrainLoading(true);
    fetchShopMap(context.ownerType, context.ownerId, { signal: controller.signal })
      .then(result => {
        if (controller.signal.aborted) return;
        const next = result.map || null;
        setTerrain(next);
        const targetLayer = Math.floor(target.y/16);
        setLayer(next?.tiles?.some(tile => tile.layerKind === 'cave' && tile.caveLayer === targetLayer) ? `cave:${targetLayer}` : 'surface');
      })
      .catch(() => { if (!controller.signal.aborted) setTerrain(null); })
      .finally(() => { if (!controller.signal.aborted) setTerrainLoading(false); });
    return () => controller.abort();
  }, [context.ownerType, context.ownerId, target.y]);

  return <section className="space-y-4 rounded-2xl border border-white/10 bg-white/[0.015] p-4 sm:p-5" data-testid="shop-context-map">
    <div className="flex items-start justify-between gap-3">
      <div><p className="font-mono text-[10px] uppercase tracking-[0.22em] text-zinc-500">Shop context</p>
        <h3 className="mt-1 font-heading text-lg font-bold">{context.anchor?.shopAreaName || context.anchor?.warpName || 'Nearby offers'}</h3>
        <p className="mt-1 text-xs text-zinc-400">{centerLabel} · {context.shops.length} observed signs · Drag to explore</p>
      </div><MapPin className="h-5 w-5 text-indigo-300"/>
    </div>
    <div className="flex flex-wrap gap-2">
      <label className="flex items-center gap-2 text-xs text-zinc-400">Layer
        <select aria-label="Map height band" className={`${control} bg-bg-base`} value={layer} onChange={e=>{setLayer(e.target.value);setFocused(null);}}>
          <option value="surface">Surface overview</option>
          {caveLayers.map(value=><option key={value} value={`cave:${value}`}>Y {value*16}–{value*16+15}</option>)}
        </select>
      </label>
      <select aria-label="Map seller" className={`${control} min-w-0 max-w-full bg-bg-base`} value={seller} onChange={e=>{setSeller(e.target.value);setFocused(null);}}>
        <option value="">All sellers</option>{sellers.map(s=><option key={s}>{s}</option>)}
      </select>
    </div>
    <div className="flex flex-wrap items-center gap-2">
      <button className={control} aria-label="Zoom out map" disabled={zoom <= 1} onClick={()=>{setZoom(z=>Math.max(1,z/1.5));setFocused(null);}}><Minus className="h-3.5 w-3.5"/></button>
      <button className={control} aria-label="Zoom in map" disabled={zoom >= 6} onClick={()=>{setZoom(z=>Math.min(6,z*1.5));setFocused(null);}}><Plus className="h-3.5 w-3.5"/></button>
      <button className={control} onClick={()=>{setZoom(1);setCenter(context.center);setFit(fittedMapRadius(context.center,context.shops,context.arrivals));setFocused(null);}}><Maximize2 className="h-3.5 w-3.5"/>Fit all</button>
      <span className="ml-auto font-mono text-[10px] text-zinc-500">{zoom.toFixed(1)}× · {step}-block grid</span>
    </div>
    <div className="overflow-hidden rounded-xl border border-white/10 bg-[radial-gradient(circle_at_center,rgba(99,102,241,0.12),transparent_70%)]">
      <svg viewBox="0 0 480 480" role="group" aria-label="Coordinate map of observed signs and warp arrivals" className={`block w-full touch-none select-none ${dragging?'cursor-grabbing':'cursor-grab'}`} data-map-radius={radius} data-center-x={center.x} data-center-z={center.z}
        onPointerDown={startDrag} onPointerMove={moveDrag} onPointerUp={endDrag} onPointerCancel={endDrag}
        onLostPointerCapture={event=>{if(event.target===event.currentTarget) endDrag(event);}}
        onClickCapture={event=>{if(suppressClick.current){event.preventDefault();event.stopPropagation();suppressClick.current=false;}}}>
        <title>{centerLabel}; select a marker to inspect offers</title>
        <defs><clipPath id={viewportId}><rect x="40" y="40" width="400" height="400" rx="4" /></clipPath></defs>
        <g clipPath={`url(#${viewportId})`}>
          {terrainTiles.map(tile => <image key={`${tile.layerKind}:${tile.caveLayer}:${tile.filename}`} href={tile.assetUrl}
            x={projectX(tile.minX)} y={projectZ(tile.minZ)} width={(tile.maxX-tile.minX)*scale} height={(tile.maxZ-tile.minZ)*scale}
            preserveAspectRatio="none" opacity="0.82" style={{imageRendering:'pixelated'}} />)}
        </g>
        {ticks(center.x).map(x=><line key={`x${x}`} x1={projectX(x)} x2={projectX(x)} y1="40" y2="440" stroke="#52525b" strokeOpacity=".35" strokeDasharray="2 5"/>)}
        {ticks(center.z).map(z=><line key={`z${z}`} y1={projectZ(z)} y2={projectZ(z)} x1="40" x2="440" stroke="#52525b" strokeOpacity=".35" strokeDasharray="2 5"/>)}
        <text x="240" y="24" textAnchor="middle" fill="#a1a1aa" fontSize="11">N ↑</text>
        <text x="458" y="244" textAnchor="middle" fill="#a1a1aa" fontSize="11">E</text>
        {[...markerGroups].map(([key, rows]) => {
          const x=rows.reduce((sum,s)=>sum+projectX(s.x),0)/rows.length;
          const y=rows.reduce((sum,s)=>sum+projectZ(s.z),0)/rows.length;
          const selected=rows.some(s=>sameShopPosition(s,target));
          return <g key={key} role="button" tabIndex="0" aria-label={`${rows.length} offer${rows.length===1?'':'s'}: ${rows[0].itemName} by ${rows[0].seller}`}
            className="cursor-pointer outline-none focus:opacity-60" onClick={()=>selectMarker(rows)}
            onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();suppressClick.current=false;selectMarker(rows);}}}>
            <circle cx={x} cy={y} r="10" fill="transparent"/>
            <circle cx={x} cy={y} r={rows.length>1?8:5} fill={selected?'#e0e7ff':'#818cf8'} stroke={selected?'#fff':'#c7d2fe'} strokeWidth={selected?2:0.7}/>
            {rows.length>1&&<text x={x} y={y+3} textAnchor="middle" fontSize="8" fill="#18181b" pointerEvents="none">{rows.length}</text>}
            {layer==='surface'&&<text x={x+8} y={y-7} fontSize="8" fill="#f4f4f5" stroke="#18181b" strokeWidth="2" paintOrder="stroke" pointerEvents="none">Y{rows[0].y}</text>}
          </g>;
        })}
        {context.arrivals.filter(z=>Math.abs(z.centerX-center.x)<=radius&&Math.abs(z.centerZ-center.z)<=radius).map(zone=><g key={zone.id} pointerEvents="none">
          <path data-testid={zone.id===context.anchor?.id?'map-warp-anchor':undefined} transform={`translate(${projectX(zone.centerX)} ${projectZ(zone.centerZ)})`} d="M0 -9L9 7H-9Z" fill="#fbbf24" stroke="#18181b" strokeWidth="2"><title>/pw {zone.warpName} · Y {zone.centerY}</title></path>
        </g>)}
        {(layer==='surface'||Math.floor(target.y/16)===selectedCaveLayer)&&Math.abs(target.x-center.x)<=radius&&Math.abs(target.z-center.z)<=radius&&<rect x={projectX(target.x)-9} y={projectZ(target.z)-9} width="18" height="18" rx="3" fill="none" stroke="#fff" strokeWidth="2" pointerEvents="none"/>}
        <line x1="40" x2={40+step*scale} y1="458" y2="458" stroke="#a1a1aa" strokeWidth="2"/>
        <text x="40" y="474" fill="#a1a1aa" fontSize="10">{step} blocks</text>
      </svg>
    </div>
    <div className="flex flex-wrap gap-3 text-[11px] text-zinc-400"><span>△ Warp arrival</span><span>□ Selected sign</span><span>● Offer / grouped offers</span></div>
    {context.anchor&&<div className="flex items-center gap-2 rounded-sm border border-amber-400/20 bg-amber-400/[0.04] px-3 py-2 text-xs text-zinc-300"><Navigation className="h-3.5 w-3.5 text-amber-300"/><span>{centerLabel} · arrival Y {context.anchor.centerY}</span></div>}
    <p className="text-xs text-zinc-500">{visible.length} of {band.length} layer offers in view. {terrainLoading ? 'Loading terrain…' : terrainTiles.length ? `Terrain captured ${terrain?.capturedAt ? new Date(terrain.capturedAt).toLocaleDateString() : 'in game'} with Xaero’s World Map.${terrain?.stale ? ' A newer capture is recommended.' : ''}` : layer === 'surface' ? 'Terrain imagery is not published yet; showing the coordinate grid.' : `Map imagery is unavailable for Y ${selectedCaveLayer*16}–${selectedCaveLayer*16+15}; showing the coordinate grid.`}</p>
    <div className="flex items-center justify-between text-xs text-zinc-400"><span>{focusedRows.length?`${focusedRows.length} offers at this marker`:'Visible offers'}</span>{focusedRows.length>0&&<button className={control} onClick={()=>setFocused(null)}>Show all</button>}</div>
    <div className="max-h-64 space-y-2 overflow-y-auto custom-scrollbar">
      {list.map(row=><button key={shopLocationKey(row)} onClick={()=>onSelect(row)} className="flex w-full items-start justify-between gap-3 rounded-lg border border-white/10 bg-white/[0.02] p-3 text-left hover:border-indigo-400/50">
        <span className="min-w-0"><span className="block text-sm text-zinc-200">{row.itemName||row.displayItemName}</span><span className="block text-xs text-zinc-500">{row.seller} · {stockLabel(row)} · Y {row.y}</span></span><span className="shrink-0 font-mono text-xs text-indigo-300">{exactCoins(row.unitPrice)}$ each</span>
      </button>)}
    </div>
  </section>;
}
